binary_search.brute:
for each index i in nums:
    if nums[i] == target: return i
return -1

search_insert_position.brute:
for each index i in nums:
    if nums[i] >= target: return i   (found target, or the spot where it would go)
return n

find_first_and_last_position.brute:
first = -1, last = -1
for each index i in nums:
    if nums[i] == target:
        if first == -1: first = i   (only the first match sets this)
        last = i
return [first, last]

search_2d_matrix.brute:
for each row in matrix:
    for each value in row:
        if value == target: return true
return false

find_min_rotated_sorted_array.optimal:
left = 0, right = n - 1
while left < right:
    mid = (left + right) / 2
    if nums[mid] > nums[right]: left = mid + 1   (mid is on the high run: the drop is to the right)
    else: right = mid
return nums[left]

search_rotated_sorted_array.brute:
for each index i in nums:
    if nums[i] == target: return i
return -1

intersection_of_two_linked_lists.brute:
a = head_a
while a is not null:
    b = head_b
    while b is not null:
        if a is b: return a   (the same node object, not just the same value)
        b = b.next
    a = a.next
return null
